import { createHash } from 'node:crypto';

// WhatsApp message IDs generated by Baileys are uppercase hexadecimal. A stable
// ID lets the server deduplicate a retry after an uncertain network response.
export function outboundMessageId(idempotencyKey: string): string {
  return createHash('sha256').update(idempotencyKey).digest('hex').slice(0, 20).toUpperCase();
}
